public class SafeBufferHandling {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter a string: ");
        String input = scanner.nextLine();

        // Ensure buffer size matches input length
        char[] buffer = new char[input.length()];

        // Copy input characters to buffer, ensuring bounds are checked
        for (int i = 0; i < input.length(); i++) {
            if (i < buffer.length) {
                buffer[i] = input.charAt(i);
            } else {
                break; // Stop copying if buffer size is exceeded
            }
        }

        System.out.println("Buffer contents: " + new String(buffer));
    }
}

