import java.io.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class InputHandler extends HttpServlet {
    protected void doPost(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        String userInput = request.getParameter("input");
        PrintWriter out = response.getWriter();

        out.println("<html>");
        out.println("<body>");
        out.println("User input: " + encodeHtml(userInput)); // Encode user input before printing
        out.println("</body>");
        out.println("</html>");
    }

    private String encodeHtml(String input) {
        // Encode special characters to prevent XSS attacks
        return input != null ? input.replace("&", "&amp;")
                                    .replace("<", "&lt;")
                                    .replace(">", "&gt;")
                                    .replace("\"", "&quot;")
                                    .replace("'", "&#x27;")
                                    .replace("/", "&#x2F;") : "";
    }
}

