import java.util.Scanner;

public class SecureBuffer {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter a string: ");
        String userInput = scanner.nextLine();

        // Limit the size of the buffer to prevent buffer overflow
        int bufferSize = Math.min(userInput.length(), 10);
        char[] buffer = new char[bufferSize];

        // Copy user input into buffer with proper bounds checking
        for (int i = 0; i < bufferSize; i++) {
            buffer[i] = userInput.charAt(i);
        }

        System.out.println("Buffer overflow avoided!");
    }
}

