public class SecureBuffer {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter a string: ");
        String userInput = scanner.nextLine();

        // Define a maximum buffer size to prevent buffer overflow
        int maxSize = 10;

        // Check if userInput length exceeds maxSize, truncate if necessary
        if (userInput.length() > maxSize) {
            userInput = userInput.substring(0, maxSize);
            System.out.println("Input exceeds maximum size. Truncated to " + userInput);
        }

        char[] buffer = new char[maxSize];

        // Copy input to buffer safely
        for (int i = 0; i < Math.min(userInput.length(), maxSize); i++) {
            buffer[i] = userInput.charAt(i);
        }

        System.out.println("Buffer content: " + String.valueOf(buffer));
    }
}

