import java.util.Scanner;

public class SafeBuffer {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter a string: ");
        String input = scanner.nextLine(); // Use nextLine() to read the whole line

        int bufferSize = 10;
        char[] buffer = new char[bufferSize];

        // Copy only up to bufferSize characters from input to buffer
        int length = Math.min(input.length(), bufferSize);
        input.getChars(0, length, buffer, 0);

        System.out.println("Buffer contents: " + new String(buffer));
    }
}

