        System.out.print("Enter a string: ");
        String userInput = scanner.nextLine(); // Read full line

        int maxLength = 10; // Maximum buffer size
        char[] buffer = new char[maxLength];

        if (userInput.length() > maxLength) {
            System.out.println("Input string exceeds buffer size. Truncating...");
            userInput.getChars(0, maxLength, buffer, 0); // Copy only up to maxLength characters
        } else {
            userInput.getChars(0, userInput.length(), buffer, 0); // Copy all characters
        }

        System.out.println("Buffer content: " + new String(buffer));
