        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter a string: ");
        String userInput = scanner.nextLine();

        int bufferSize = 10; // Buffer size
        char[] buffer = new char[bufferSize];

        int lengthToCopy = Math.min(userInput.length(), bufferSize); // Limit copying length to buffer size

        userInput.getChars(0, lengthToCopy, buffer, 0); // Safe copying of user input

        System.out.println("Buffer contents: " + new String(buffer));
    }
}

