        response.getWriter().write("<h1>" + responseMessage + "</h1>");
        response.getWriter().write("</body></html>");
    }

    private String sanitizeInput(String input) {
        // Replace characters that have special meaning in HTML with their HTML entity equivalents
        input = input.replaceAll("&", "&amp;")
                     .replaceAll("<", "&lt;")
                     .replaceAll(">", "&gt;")
                     .replaceAll("\"", "&quot;")
                     .replaceAll("'", "&#39;");

        return input;
    }
}

