import java.util.Scanner;

public class SecureBufferExample {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter a string: ");
        String userInput = scanner.nextLine();

        // Truncate input if it exceeds buffer size
        ByteBuffer byteBuffer = StandardCharsets.UTF_8.encode(userInput);
        int length = Math.min(byteBuffer.remaining(), 10);

        byte[] buffer = new byte[length];
        byteBuffer.get(buffer, 0, length);

        System.out.println("Buffer contents: " + new String(buffer, StandardCharsets.UTF_8));
    }
}

