import java.util.Scanner;

public class SecureBufferHandling {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter a string: ");
        String input = scanner.nextLine();

        int bufferSize = 10;

        // Limit the input size to the buffer size
        if (input.length() > bufferSize) {
            System.out.println("Input size exceeds buffer size. Truncating input...");
            input = input.substring(0, bufferSize);
        }

        char[] buffer = new char[bufferSize];
        input.getChars(0, input.length(), buffer, 0);

        System.out.println("Buffer content: " + new String(buffer));
    }
}

